function skuSelect(p){return `<select id="profitSkuPicker" class="select">${p.skus.map(s=>`<option value="${safe(s.id)}" ${s.id===activeSkuId?'selected':''}>${safe(s.name)}</option>`).join('')}</select>`}
function renderProfit(p){let s=p.skus.find(x=>x.id===activeSkuId)||p.skus[0];if(!s)return `${heading('利润实验室','请先添加 SKU。')}`;activeSkuId=s.id;const result=projection(s),goal=s.targetMargin===undefined?10:n(s.targetMargin),p10=targetPrice(s,10),pGoal=targetPrice(s,goal),prices=[89.99,99.99,109.99,119.99,129.99],ads=[10,15,20,25,30];const cell=(price,ad)=>{let v=profit(s,price,ad).margin;return `<div class="heat" title="售价 ${money(price)} / 广告率 ${ad}%" style="background:${v>=20?'#d6f1e2':v>=10?'#e8f5e9':v>=0?'#fff0cc':'#ffe1e1'};color:${v>=0?'#255b46':'#a43e4c'}">${rnd(v,1)}%<small>${money(price)} / ${ad}%</small></div>`};const basis=s.planBasis||'monthlyUnits';const input=(k,l,value,enabled,note='')=>`<div class="field"><label>${l}</label><input type="number" step="any" min="0" ${enabled?'':'disabled'} data-sku-field="${k}" value="${safe(value)}">${note?`<p class="caption">${note}</p>`:''}</div>`;const inputs=[['price','当前售价（USD）'],['referral','销售佣金（%）'],['ads','广告率（%）'],['returns','退货损耗预留（售价 %）'],['promotion','促销费率（%）'],['fba','FBA 单件费（USD）'],['storage','仓储分摊（USD）'],['freight','头程单件费（USD）'],['other','其他单件费（USD）']];return `${heading('售价与利润实验室','先计算单件成本和保本/目标售价，再依据预测销量自动推算月度、年度经营结果。',skuSelect(p))}<div class="grid cols4">${metric('盈亏平衡售价（0%）',priceLabel(result.breakEven),'以当前费用率计算')}${metric('10% 利润率对应售价',priceLabel(p10),'目标利润 ÷ 销售收入')}${metric(`${rnd(goal,1)}% 目标利润率售价`,priceLabel(pGoal),'目标可编辑，自动反推')}${metric('当前售价',money(s.price),'所有测算均基于此售价')}</div><section class="section"><div class="grid cols2"><div class="card"><div class="row-head"><h3 class="section-title" style="margin:0">成本、售价与目标利润率</h3><span class="pill">当前 SKU</span></div><div class="form-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="field wide"><label>采购成本（USD · 自动同步 SKU）</label><input type="text" value="${safe(money(skuPurchaseUSD(s)))}" readonly aria-label="自动同步采购成本 USD"><p class="caption">${safe(skuPurchaseSource(s))}</p><button type="button" class="btn tiny" data-action="goto" data-target="product">在 SKU 页面修改采购价 / 汇率 →</button></div>${inputs.map(([k,l])=>field(k,l,s[k])).join('')}${field('targetMargin','自定义目标利润率（%）',goal)}</div><p class="caption">本页金额类费用统一以 USD / 件录入和展示。采购成本来自同一 SKU 的人民币采购价及汇率；已有 USD 手动覆盖值继续保留。佣金、广告、退货预留和促销按售价比例估算。</p>${n(s.purchaseRmb)>0&&n(s.fx)<=0&&n(s.costUsdOverride)<=0?'<div class="warn">当前汇率无效，采购成本及利润测算暂不可用。请到 SKU 页面修正汇率。</div>':''}${n(s.fba)===0||n(s.freight)===0?'<div class="warn">费用提醒：FBA 或头程单件费当前为 $0.00，请确认这是否是真实费用。缺少必要物流成本时，利润及保本售价可能明显偏乐观。</div>':''}</div><div class="card"><h3 class="section-title">单件成本拆解（USD）</h3>${horizontalBars([...result.baseCosts.map(([k,v])=>({k,v})),{k:'佣金',v:n(s.price)*n(s.referral)/100},{k:'广告',v:n(s.price)*n(s.ads)/100},{k:'退货预留',v:n(s.price)*n(s.returns)/100},{k:'促销',v:n(s.price)*n(s.promotion)/100}],'money')}<div class="split finance-total"><b>单件总成本</b><strong>${money(result.totalCost)}</strong></div><div class="split finance-total"><b>单件利润</b><strong class="${result.profit>=0?'u-green':'u-red'}">${money(result.profit)}</strong></div><div class="split finance-total"><b>单件利润率</b><strong class="${result.margin>=0?'u-green':'u-red'}">${rnd(result.margin,2)}%</strong></div></div></div></section><section class="section"><div class="card"><div class="row-head"><h3 class="section-title" style="margin:0">月度 / 年度销售预测</h3><span class="pill">用户预测 · 非竞品实际销量</span></div><div class="row-head" style="margin-top:12px"><label class="field" style="display:flex;align-items:center;gap:10px">选择预测输入方式 <select id="planBasisPicker" class="select"><option value="monthlyUnits" ${basis==='monthlyUnits'?'selected':''}>手动填写月销量</option><option value="annualUnits" ${basis==='annualUnits'?'selected':''}>手动填写年销量</option><option value="annualRevenue" ${basis==='annualRevenue'?'selected':''}>手动填写年销售额</option></select></label><span class="note">只编辑选择的一项，其余指标自动联动；月份按全年 ÷ 12 平均。</span></div><div class="form-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${input('monthlyPlan','预计月销量（件）',basis==='monthlyUnits'?s.monthlyPlan:rnd(result.monthlyUnits,2),basis==='monthlyUnits')}${input('annualUnitsPlan','预计年销量（件）',basis==='annualUnits'?s.annualUnitsPlan:rnd(result.annualUnits,2),basis==='annualUnits')}${input('annualRevenuePlan','预计年销售额（USD）',basis==='annualRevenue'?s.annualRevenuePlan:rnd(result.annualRevenue,2),basis==='annualRevenue')}</div>${basis==='annualRevenue'?'<p class="caption">按收入反推销量时允许小数作为预算等效销量，不代表实际可以销售零点几件；正式备货须按整数规划。</p>':''}<div class="data-table-wrap" style="margin-top:22px"><table><thead><tr><th>测算指标</th><th class="num">单件</th><th class="num">月度预测</th><th class="num">年度预测</th></tr></thead><tbody><tr><td>销售数量（件）</td><td class="num">1</td><td class="num">${qty(result.monthlyUnits)}</td><td class="num">${qty(result.annualUnits)}</td></tr><tr><td>销售收入（USD）</td><td class="num">${money(s.price)}</td><td class="num">${money(result.monthlyRevenue)}</td><td class="num">${money(result.annualRevenue)}</td></tr><tr><td>全部成本（USD）</td><td class="num">${money(result.totalCost)}</td><td class="num">${money(result.monthlyCost)}</td><td class="num">${money(result.annualCost)}</td></tr><tr><td>利润（USD）</td><td class="num ${result.profit>=0?'u-green':'u-red'}">${money(result.profit)}</td><td class="num ${result.monthlyProfit>=0?'u-green':'u-red'}">${money(result.monthlyProfit)}</td><td class="num ${result.annualProfit>=0?'u-green':'u-red'}">${money(result.annualProfit)}</td></tr><tr><td>销售利润率</td><td class="num">${rnd(result.margin,2)}%</td><td class="num">${rnd(result.margin,2)}%</td><td class="num">${rnd(result.margin,2)}%</td></tr></tbody></table></div><p class="caption">总成本 = 单件总成本 × 销售数量；利润 = 销售额 − 总成本。结果属于贡献利润，尚未扣除团队工资、软件订阅等未填写的企业期间固定费用。</p></div></section><section class="section"><div class="card"><div class="row-head"><h3 class="section-title" style="margin:0">售价 × 广告率敏感性分析</h3><span class="pill">单件利润率</span></div><div class="heatmap">${prices.flatMap(pr=>ads.map(ad=>cell(pr,ad))).join('')}</div><p class="caption">横向广告费率依次为 10%、15%、20%、25%、30%；纵向售价依次为 $89.99、$99.99、$109.99、$119.99、$129.99。</p></div></section><section class="section"><h3 class="section-title">全部 SKU 成本和年度预测对比</h3><div class="card data-table-wrap"><table><thead><tr><th>SKU</th><th class="num">售价</th><th class="num">单件总成本</th><th class="num">单件利润</th><th class="num">利润率</th><th class="num">保本售价</th><th class="num">10% 售价</th><th class="num">预计年销量</th><th class="num">预计年销售额</th><th class="num">预计年利润</th></tr></thead><tbody>${p.skus.map(x=>{let v=projection(x);return `<tr><td>${safe(x.name)}</td><td class="num">${money(x.price)}</td><td class="num">${money(v.totalCost)}</td><td class="num">${money(v.profit)}</td><td class="num">${rnd(v.margin,2)}%</td><td class="num">${priceLabel(v.breakEven)}</td><td class="num">${priceLabel(targetPrice(x,10))}</td><td class="num">${qty(v.annualUnits)}</td><td class="num">${money(v.annualRevenue)}</td><td class="num">${money(v.annualProfit)}</td></tr>`}).join('')}</tbody></table></div></section>`;}

function generateRuleReport(p){const core=compValid(p).filter(c=>riskTier(c)==='core'),alt=compValid(p).filter(c=>riskTier(c)==='alternative'),review=compValid(p).filter(c=>riskTier(c)==='review'),all=[...core,...alt],stats=dedupeSummary(all),s=p.skus[0],pr=s?profit(s):null,priceMid=median(core.map(c=>c.price)),comparable=s?core.filter(c=>Math.abs(c.price-n(s.price))<=n(s.price)*.15):[];return `【报告类型】基于规则的调研草稿（并非 AI 自动核实）
【项目】${p.name} | Amazon 美国站 | ${today()}

一、样本结构
核心候选 ${core.length} 条、其他材质替代品 ${alt.length} 条、材质待核实 ${review.length} 条，已排除 ${p.competitors.filter(c=>c.excluded).length} 条非同类产品。导入文件中的低价筛除数量：${p.imports[p.imports.length-1]?.rejectedCount||0} 条。核心及替代的筛选样本不等于 Amazon 全市场。

二、销量与市场估计
核心 + 替代竞品：未经去重月销 ${num(stats.raw)} 件；疑似共享销量保守情景约 ${num(stats.conservative)} 件。保守估算月销售额 ${money(stats.revenueConservative)}，当前月年化销额 ${money(stats.revenueConservative*12)}。疑似重复组 ${stats.riskGroups} 组（涉及 ${stats.riskRows} 条记录）。这仅是基于品牌、月销、评论和变体相同的风险推断，不能代替真实父体 ASIN 核验。

三、定价接受度
核心竞品中位售价 ${money(priceMid)}。${s?`当前 SKU 计划售价 ${money(s.price)}，核心竞品在目标价 ±15% 内共有 ${comparable.length} 条；${comparable.length?'应核对它们的购买需求、评价及产品差异。':'同价位样本不足，无法确认消费者对该售价的接受度。'}`:'尚未设置 SKU，无法对比目标售价。'}

四、单件盈利
${s?`当前售价 ${money(s.price)}，单件总成本 ${money(pr.totalCost)}，单件贡献利润 ${money(pr.profit)}，利润率 ${rnd(pr.margin,2)}%，保本售价 ${money(pr.breakEven)}。这些结果依赖用户录入的采购、FBA、广告、退货等费用假设。`:'暂无 SKU 定价数据。'}

五、主要数据缺口
- ${review.length} 条材质或用途待核实，当前不得计入直接竞争样本。
- 第三方月销是估算，不是 Amazon 官方销售订单；目前没有历史 12 个月销售数据。
- 共享父体风险尚未通过父 ASIN、产品页面和子体销量核验。
- 尚缺真实广告转化、退货损耗与官方 FBA 计费核算。

六、初步判断
建议先核实最相近的核心竞品与产品差异，再用保守需求情景和真实费用检验目标售价。该建议是规则草稿，必须由用户复核后形成最终决策。

【数据来源】${p.imports.map(x=>x.file).join('、')||'手工录入'}。`;}
function renderReport(p){return `${heading('市场调研结论','基于竞品与 SKU 数据生成可编辑的判断草稿。正式 AI 接口尚未连接。',`<button class="btn primary" data-action="generate-report">✧ 生成规则分析草稿</button>`)}<div class="warn">当前按钮采用可审计的规则模板，不会调用大模型；正式版本接入 AI 后，才支持更深入的功能差异、风险推理及证据引用。本原型不会将规则生成结果冒充 AI 内容。</div><section class="section"><div class="grid cols2"><div class="card"><h3 class="section-title">编辑最终结论</h3><textarea id="reportEdit" class="report-edit" placeholder="点击‘生成规则分析草稿’，然后修改或补充结论...">${safe(p.report||'')}</textarea><div class="toolbar end"><button class="btn primary" data-action="save-report">保存结论</button></div></div><div class="card"><h3 class="section-title">结论的证据检查清单</h3>${[['有直接竞品样本',compValid(p).some(c=>c.category.startsWith('直接'))],['有售价与销量数据',compValid(p).some(c=>c.price&&c.monthly)],['有至少一个 SKU',p.skus.length>0],['有费用与成本参数',p.skus.some(s=>s.fba&&s.purchaseRmb)],['有连续12个月历史数据',false],['有真实消费者调研数据',false]].map(([k,v])=>`<div class="split" style="padding:13px 0;border-bottom:1px solid #f0f2f6"><span style="font-size:12px">${k}</span><span class="pill ${v?'green':'yellow'}">${v?'已具备':'仍需补充'}</span></div>`).join('')}<p class="caption">每次正式保存版本时，结论将连同当时竞品与成本参数一起进入快照。</p></div></div></section>`}
function snapshot(p){const {versions,...data}=p;return clone(data)}
function saveVersion(){const p=project();let note=prompt('版本说明（例如：完成首次调研 / 更新竞品价格）','完成一次调研');if(note===null)return;p.versions.push({id:uid(),index:p.versions.length+1,at:new Date().toISOString(),note,snapshot:snapshot(p)});save();toast(`已创建 V${p.versions.length}，旧版本不会被覆盖`);if(page==='history')render()}
function renderHistory(p){const v=p.versions.slice().reverse();return `${heading('历史版本与复盘','正式版本不可修改；恢复旧版会创建新版本，原记录保留。',`<button class="btn primary" data-action="save-version">＋ 保存新版本</button>`)}<div class="grid cols2"><div class="card"><h3 class="section-title">版本时间线</h3>${v.length?v.map(x=>`<div class="version-line"><div class="split"><b>V${x.index} · ${safe(x.note||'无备注')}</b><span class="pill gray">${safe(x.at.slice(0,16).replace('T',' '))}</span></div><p class="note">${x.snapshot.skus.length} SKU · ${x.snapshot.competitors.length} 竞品</p><div class="toolbar"><button class="btn tiny" data-action="download-version" data-id="${safe(x.id)}">导出快照 JSON</button><button class="btn tiny" data-action="select-version" data-id="${safe(x.id)}">${selectedVersionIds.includes(x.id)?'已选中':'选中比较'}</button><button class="btn tiny red" data-action="restore-version" data-id="${safe(x.id)}">恢复为新版本</button></div></div>`).join(''):'<div class="empty">尚无正式版本。点击「保存新版本」，保存当前市场数据与所有 SKU 的状态。</div>'}</div><div class="card"><h3 class="section-title">版本差异对比</h3><p class="sub">选中两个历史版本后自动对比。</p>${versionCompare(p)}</div></div><p class="footer-info">本机原型的版本保存在浏览器 localStorage，不具备云端容灾能力。请定期导出项目 JSON。生产版会改成 PostgreSQL 不可变快照和云端存储。</p>`}
function versionCompare(p){const vs=selectedVersionIds.map(id=>p.versions.find(v=>v.id===id)).filter(Boolean);if(vs.length<2)return `<div class="empty">请从左侧选中两个版本。</div>`;const [a,b]=vs;const cmp=s=>{let cs=s.competitors.filter(c=>!c.excluded),m=sum(cs,c=>c.monthly);return {s:s.skus.length,c:cs.length,m,rev:sum(cs,c=>c.monthly*c.price),r:s.report?.length||0}};const x=cmp(a.snapshot),y=cmp(b.snapshot);return `<table><thead><tr><th>指标</th><th>V${a.index}</th><th>V${b.index}</th><th>变化</th></tr></thead><tbody>${[['SKU 数','s'],['有效竞品数','c'],['月销下界','m'],['月销售额下界','rev'],['报告字符数','r']].map(([label,key])=>`<tr><td>${label}</td><td>${num(x[key])}</td><td>${num(y[key])}</td><td>${y[key]-x[key]>0?'+':''}${num(y[key]-x[key])}</td></tr>`).join('')}</tbody></table><div class="caption">此处为主要 KPI 差异；详细版本内容可导出 JSON 对照。</div>`}
function openModal(body){$('#modalRoot').innerHTML=`<div class="modal">${body}</div>`;$('#modalRoot').classList.remove('hidden');$('#modalRoot').onclick=e=>{if(e.target.id==='modalRoot')closeModal()}}
