function compModal(c){openModal(`<h3>${c?'编辑竞品':'手动添加竞品'}</h3><p class="sub">只填写常用字段，分类可直接修改。原始文件不受影响。</p><form id="compForm"><div class="form-grid" style="margin-top:18px">${inputForm('asin','ASIN',c?.asin||'')}${inputForm('brand','品牌',c?.brand||'')}${inputForm('category','竞品分类',c?.category||'待核实')}${inputForm('material','材质',c?.material||'')}${inputForm('purpose','用途',c?.purpose||'')}${inputForm('price','售价 USD',c?.price||0,'number')}${inputForm('monthly','估计月销',c?.monthly||0,'number')}${inputForm('reviews','评论数',c?.reviews||0,'number')}${inputForm('date','上架日期',c?.date||'','text')}</div><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">取消</button><button type="submit" class="btn primary">保存竞品</button></div></form>`);$('#compForm').onsubmit=e=>{e.preventDefault();const vals=Object.fromEntries(new FormData(e.target).entries()),p=project();if(!/^[A-Z0-9]{10}$/.test(String(vals.asin).toUpperCase()))return toast('ASIN 应为10位数字字母');const out={...vals,asin:vals.asin.toUpperCase(),price:n(vals.price),monthly:n(vals.monthly),reviews:n(vals.reviews),monthlyRaw:String(vals.monthly),isLowerBound:false};if(c){Object.assign(c,out)}else{p.competitors.push({...out,id:uid(),rating:0,variants:0,excluded:false,source:'网页手动录入',sourceRow:0})}markDuplicateRisks(p.competitors);save();closeModal();render();toast('竞品已保存')}}
function openExport(){openModal(`<h3>导出项目</h3><p class="sub">选择导出格式。本机原型支持项目 JSON、竞品 CSV 与浏览器 PDF 打印。</p><div class="grid cols3" style="margin-top:22px"><button class="project-card" data-action="export-json"><b>JSON 完整项目</b><p class="note">可重新导入的完整项目备份，包含版本与原始记录字段</p></button><button class="project-card" data-action="export-csv"><b>CSV 竞品表</b><p class="note">包含分类、ASIN、价格、月销及年化数据</p></button><button class="project-card" data-action="export-print"><b>打印 / PDF</b><p class="note">打开浏览器打印面板，选择“另存为 PDF”</p></button></div><div class="modal-footer"><button class="btn" data-action="close-modal">取消</button></div>`)}
