function exportJson(data=project(),file){download(file||`市场调研-${project().name}-${today()}.json`,new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));toast('已导出 JSON 文件')}
function exportCsv(){let p=project(),cols=['分类','材质','用途','ASIN','品牌','售价USD','估计月销量','估计月销售额USD','年化销量(非历史)','评论数','上架日期','重复销量风险','排除','排除原因','原表名','原表行号'];const rows=p.competitors.map(c=>[c.category,c.material,c.purpose,c.asin,c.brand,c.price,c.monthly,n(c.monthly)*n(c.price),n(c.monthly)*12,c.reviews,c.date,c.duplicateRisk?'需核查':'',c.excluded?'是':'否',c.excludeReason||'',c.sourceSheet,c.sourceRow]);let lines=[cols,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(','));download(`竞品决策数据-${today()}.csv`,new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));toast('已导出精简 CSV，原始 Excel 仍可在导入记录中下载')}
// IndexedDB original-file archive: local-only in this prototype.
function dbOpen(){return new Promise((resolve,reject)=>{const req=indexedDB.open('mresearch-original-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function putFile(key,blob){const db=await dbOpen();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(blob,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function getFile(key){const db=await dbOpen();const v=await new Promise((resolve,reject)=>{const tx=db.transaction('files');const req=tx.objectStore('files').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return v}

function riskTier(c){const category=String(c.category||''),s=category+' '+String(c.purpose||'');if(c.excluded||/非同类|已排除/.test(category))return 'unrelated';if(/待核实|未分类|需核实/.test(category))return 'review';if(/浴缸盖/.test(String(c.purpose||'')))return 'unrelated';if(/亚克力|直接竞品|核心候选/.test(s))return 'core';if(/高端木质|木质|金属托盘|替代|间接竞品/.test(s))return 'alternative';return 'review'}
function matName(c){return String(c.material||c.category||'待核实').replace(/[（(]待该?ASIN核实[）)]|（未独立核实）|候选/g,'').trim()||'待核实'}
function duplicateKey(c){if(!c.monthly||!c.brand||!c.reviews||!c.variants)return '';return [String(c.brand).trim().toLowerCase(),n(c.monthly),n(c.reviews),n(c.variants)].join('|')}
function markDuplicateRisks(rows){const groups={};rows.forEach(c=>{c.duplicateRisk=false;const k=duplicateKey(c);if(k)(groups[k]??=[]).push(c)});Object.values(groups).filter(v=>v.length>1).forEach(v=>v.forEach(c=>c.duplicateRisk=true));}
function dedupeSummary(rows){const groups=new Map();rows.forEach(c=>{const k=c.duplicateRisk?duplicateKey(c):`asin:${c.asin}`;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(c)});const all=[...groups.values()];return {raw:sum(rows,c=>n(c.monthly)),conservative:sum(all,g=>Math.max(...g.map(c=>n(c.monthly)))),revenueRaw:sum(rows,c=>n(c.monthly)*n(c.price)),revenueConservative:sum(all,g=>Math.max(...g.map(c=>n(c.monthly)*n(c.price)))),riskGroups:all.filter(g=>g.length>1).length,riskRows:sum(all.filter(g=>g.length>1),g=>g.length)}}
function priceBands(rows){if(!rows.length)return [];const min=Math.min(...rows.map(c=>n(c.price))),max=Math.max(...rows.map(c=>n(c.price)));const floor=Math.floor(min/10)*10,step=10;let arr=[];for(let start=floor;start<=max&&arr.length<15;start+=step){arr.push({k:`$${start}–${start+step-0.01}`,items:rows.filter(c=>c.price>=start&&c.price<start+step)})}if(max>=floor+15*step)arr.push({k:`$${floor+150}+`,items:rows.filter(c=>c.price>=floor+150)});return arr.filter(b=>b.items.length)}
function compactMoney(v){return Math.abs(v)>=1e6?'$'+(v/1e6).toFixed(2)+'M':Math.abs(v)>=1e3?'$'+(v/1e3).toFixed(1)+'K':money(v)}
function uniqueAsins(s){const seen=new Set();return s.rows.slice(s.headerIndex+1).filter(r=>{const a=String(r[s.map.asin]||'').trim().toUpperCase();if(!/^[A-Z0-9]{10}$/.test(a)||seen.has(a))return false;seen.add(a);return true})}
function smartWorkbook(wb,fileName){const sections=findSections(wb);let master=sections.find(s=>/^02_.*(高价|全部)/.test(s.sheet))||sections.find(s=>/Product-US|^原始|^商品数据/.test(s.sheet))||sections.filter(x=>!/^0[3-9]_/.test(x.sheet)).sort((a,b)=>uniqueAsins(b).length-uniqueAsins(a).length)[0]||sections.sort((a,b)=>uniqueAsins(b).length-uniqueAsins(a).length)[0];const raw=sections.find(s=>/Product-US|^原始|^商品数据/.test(s.sheet));const low=sections.find(s=>/09_.*低于/.test(s.sheet));const qual=sections.find(s=>/^02_/.test(s.sheet));const categories=new Map(),evidence=new Map();const catSpecs=[[/^03_/, '亚克力候选'],[/^04_/, '高端木质'],[/^05_/, '金属托盘'],[/^06_/, '浴缸盖非同类'],[/^07_/, '材质待核实']];for(const sec of sections){let match=catSpecs.find(([reg])=>reg.test(sec.sheet));if(!match)continue;for(const r of uniqueAsins(sec))categories.set(String(r[sec.map.asin]).trim().toUpperCase(),match[1])}
const n08=wb.SheetNames.find(n=>/^08_.*分类依据/.test(n));if(n08){const arr=XLSX.utils.sheet_to_json(wb.Sheets[n08],{header:1,defval:'',raw:false});const headers=arr[0]||[];const h=k=>headers.findIndex(x=>String(x).trim()===k);for(const row of arr.slice(1)){const a=String(row[h('ASIN')]||'').toUpperCase().trim();if(!/^[A-Z0-9]{10}$/.test(a))continue;evidence.set(a,{purpose:String(row[h('用途分类')]||''),material:String(row[h('材质分类（含待核实）')]||''),feature:String(row[h('产品特点')]||''),evidence:String(row[h('材质证据等级')]||''),reason:String(row[h('判断与提醒')]||'')})}}
let floor=0;const metaName=wb.SheetNames.find(n=>/^10_.*数据质量/.test(n));if(metaName){const arr=XLSX.utils.sheet_to_json(wb.Sheets[metaName],{header:1,defval:''});for(const row of arr){const txt=row.map(v=>String(v||'')).join(' ');if(/筛选范围/.test(txt)){const m=txt.match(/(?:≥|>=)\s*\$?\s*(\d+(?:\.\d+)?)/);if(m)floor=Number(m[1])}}}
if(!floor&&qual){const m=String(fileName).match(/(\d+(?:\.\d+)?)\s*美元以上/);floor=m?Number(m[1]):0}
return {sections,master,raw,low,qual,categories,evidence,floor,sourceCount:raw?uniqueAsins(raw).length:master?uniqueAsins(master).length:0}}
const mappingAliases={asin:['asin','asin码','商品asin'],brand:['brand','品牌','品牌名'],price:['price','价格','售价','价格($)','售价($)','售价($)'],monthly:['monthly sales','月销量','子体月销','月销','预估月销量','monthly units','月销量（原值）'],rating:['rating','评分','星级'],reviews:['reviews','review count','评论数','评价数','评分数'],date:['上架时间','上架日期','date','listing date'],variants:['变体数','变体数量'],seller:['卖家所属地','seller'],fulfillment:['配送方式','fulfillment'],image:['图片参考','image']};
function hnorm(x){return String(x??'').toLowerCase().replace(/[\s\r\n_*（）()\-]/g,'').trim()}
function guessMap(header){const map={};for(let [key,aliases]of Object.entries(mappingAliases)){let match=header.findIndex(x=>aliases.some(alias=>hnorm(x)===hnorm(alias)));if(match>=0)map[key]=match}return map}
function findSections(workbook){let results=[];workbook.SheetNames.forEach((name,sheetIndex)=>{const rows=XLSX.utils.sheet_to_json(workbook.Sheets[name],{header:1,defval:'',raw:false});let best=null;rows.slice(0,150).forEach((r,i)=>{let map=guessMap(r);let matches=Object.keys(map).length;const hasAsin=map.asin!==undefined;if(hasAsin&&matches>=3&&(!best||matches>best.matches))best={sheetIndex,sheet:name,rows,headerIndex:i,headers:r,map,matches}});if(best)results.push(best)});return results}
function showImport(file,wb){const smart=smartWorkbook(wb,file.name);pending={file,wb,smart,sections:smart.sections};if(!smart.master)return toast('没有找到包含 ASIN、月销量和售价的竞品表，请确认原始表头或导出格式。');importSheetIndex=smart.sections.indexOf(smart.master);renderImportModal()}
function renderImportModal(){if(!pending)return;const x=pending.smart,s=pending.sections[importSheetIndex];const data=uniqueAsins(s).slice(0,5),fields=[['asin','ASIN（必填）'],['brand','品牌'],['price','售价'],['monthly','月销量'],['reviews','评论 / 评分数'],['date','上架日期'],['variants','变体数'],['seller','卖家地区']];const priceMin=pending.priceMin??x.floor;const qualified=uniqueAsins(s).filter(r=>importedValue(r[s.map.price]).number>=n(priceMin));const byCategory={};qualified.forEach(r=>{const cat=x.categories.get(String(r[s.map.asin]||'').toUpperCase().trim())||'待核实';byCategory[cat]=(byCategory[cat]||0)+1});openModal(`<h3>确认智能导入 · 保留真正有用的数据</h3><p class="sub">${safe(pending.file.name)} · ${x.sourceCount} 条原始 ASIN · 智能识别 ${x.categories.size} 条已分类依据。界面不重复导入各分类工作表。</p><div class="grid cols3" style="margin:18px 0">${metric('原始 ASIN',num(x.sourceCount),'整个 Excel 的原始记录')}${metric('价格达标',num(qualified.length),'以选定工作表统计')}${metric('低于门槛',num(Math.max(0,x.sourceCount-qualified.length)),'仅保留数量和原因')}</div><div class="row-head"><div class="toolbar"><label class="field tiny-label">选择主数据表<select id="importSection" class="select">${pending.sections.map((item,i)=>`<option value="${i}" ${i===importSheetIndex?'selected':''}>${safe(item.sheet)} · ${uniqueAsins(item).length} 行</option>`).join('')}</select></label><label class="field tiny-label">最低售价（USD）<input id="importPriceMin" type="number" min="0" step="0.01" value="${n(priceMin)}" style="width:120px"></label></div></div><p class="note">分类依据：${Object.entries(byCategory).map(([k,v])=>`${safe(k)} ${v} 条`).join(' · ')||'无'}。材质无法可靠识别时标为「待核实」。</p><details class="mapping-details"><summary>表头识别预览与校正（可选） · 匹配 ${Object.keys(s.map).length} 个字段</summary><div class="form-grid" style="margin:14px 0">${fields.map(([k,label])=>`<div class="field"><label>${label}</label><select class="select" data-map-field="${k}"><option value="">不导入</option>${s.headers.map((item,i)=>`<option value="${i}" ${s.map[k]===i?'selected':''}>${i+1}. ${safe(item||'(空白)')}</option>`).join('')}</select></div>`).join('')}</div><div class="data-table-wrap"><table><thead><tr>${s.headers.slice(0,12).map(x=>`<th>${safe(x)}</th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${s.headers.slice(0,12).map((x,i)=>`<td>${safe(String(r[i]||'').slice(0,55))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details><div class="warn" style="margin-top:14px">导入后仅在项目内保存必要字段，完整 Excel 独立存档；已有相同 ASIN 将更新而不会重复累计。价格不足门槛的数据不进入日常竞品列表。</div><div class="modal-footer"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="confirm-import">确认，生成 Dashboard</button></div>`)}
function importedValue(raw){const str=String(raw??'').trim();const numx=Number(str.replace(/[^0-9.-]/g,''));return {str,number:Number.isFinite(numx)?numx:0,lowerBound:/\+|≥|以上|不少于/.test(str)}}
function excelDate(s){if(!s)return '';let v=String(s).trim();if(/^\d{5}(\.0)?$/.test(v)){let d=new Date(Date.UTC(1899,11,30)+Number(v)*86400000);return d.toISOString().slice(0,10)}return v.slice(0,10)}
async function confirmImport(){if(!pending)return;const sec=pending.sections[importSheetIndex],smart=pending.smart,p=project();const map={...sec.map};document.querySelectorAll('[data-map-field]').forEach(el=>{if(el.value==='')delete map[el.dataset.mapField];else map[el.dataset.mapField]=Number(el.value)});if(map.asin===undefined||map.price===undefined||map.monthly===undefined)return toast('至少需要 ASIN、价格和月销量字段');const min=Math.max(0,n(document.querySelector('#importPriceMin')?.value??smart.floor));const original=smart.raw?uniqueAsins(smart.raw).length:uniqueAsins(sec).length;let count=0,invalid=0,priceRejected=0,updated=0;const seen=new Set();const values=[];let category='待核实';for(let i=sec.headerIndex+1;i<sec.rows.length;i++){const row=sec.rows[i],a=String(row[map.asin]||'').toUpperCase().trim();if(!/^[A-Z0-9]{10}$/.test(a)){const label=row.map(x=>String(x||'')).join(' ').trim();if(/直接竞品|间接竞品/.test(label))category=label.slice(0,45);continue}if(seen.has(a))continue;seen.add(a);const price=importedValue(row[map.price]),sales=importedValue(row[map.monthly]);if(price.number<=0){invalid++;continue}if(price.number<min){priceRejected++;continue}const get=k=>map[k]===undefined?'':String(row[map[k]]||'').trim();const info=smart.evidence.get(a)||{},classification=smart.categories.get(a)||(info.material?/亚克力/.test(info.material)?'亚克力候选':'材质待核实':category);const unrelated=/非同类|浴缸盖/.test(classification);values.push({asin:a,brand:get('brand'),price:price.number,monthly:sales.number,monthlyRaw:sales.str,isLowerBound:sales.lowerBound,reviews:importedValue(get('reviews')).number,rating:importedValue(get('rating')).number,variants:importedValue(get('variants')).number,date:excelDate(get('date')),category:classification,material:info.material||'',purpose:info.purpose||'',evidence:info.evidence||'未核实',feature:info.feature||'',reason:info.reason||'',excluded:unrelated,excludeReason:unrelated?'用途不符：非同类产品':'',source:pending.file.name,sourceSheet:sec.sheet,sourceRow:i+1});count++}
const byAsin=new Map(p.competitors.map((c,i)=>[c.asin,i]));for(const row of values){if(byAsin.has(row.asin)){const old=p.competitors[byAsin.get(row.asin)];p.competitors[byAsin.get(row.asin)]={...old,...row,id:old.id};updated++}else{p.competitors.push({...row,id:uid()});byAsin.set(row.asin,p.competitors.length-1)}}markDuplicateRisks(p.competitors);let key=null;try{key=uid();await putFile(key,pending.file)}catch(e){key=null;toast('原始文件未能在浏览器保存，请另行保留自己的 Excel 备份')}
const rejectedCount=smart.raw&&sec.sheet!==smart.raw.sheet?Math.max(0,original-count):priceRejected;const reviewCount=values.filter(c=>riskTier(c)==='review'&&!c.excluded).length;const last={id:uid(),file:pending.file.name,fileKey:key,date:today(),rows:count,updated,sourceCount:original,qualifiedCount:count,rejectedCount,reviewCount,invalid,sourceSheet:sec.sheet,priceMin:min};p.imports.push(last);p.filters={...(p.filters||{}),priceMin:min};save();pending=null;closeModal();dashboardScope='自动';dashboardMaterial='全部';navigate('dashboard');toast(`已导入 ${count} 条、更新 ${updated} 条；${rejectedCount} 条低价/非候选数据从分析视图隐藏`)}
async function dispatchChange(e){const t=e.target,p=project();if(t.id==='xlsxInput'){const file=t.files?.[0];if(!file)return;if(typeof XLSX==='undefined')return toast('Excel 解析组件未加载。请确认已连接互联网并刷新页面。');try{const buf=await file.arrayBuffer();showImport(file,XLSX.read(buf,{type:'array',cellDates:true}))}catch(err){toast('读取 Excel 失败：'+err.message)}return}
if(t.id==='importSection'){importSheetIndex=Number(t.value);renderImportModal();return}if(t.id==='importPriceMin'){pending.priceMin=Math.max(0,n(t.value));if(pending.smart.raw&&pending.smart.qual&&pending.priceMin<pending.smart.floor&&pending.sections[importSheetIndex].sheet===pending.smart.qual.sheet){importSheetIndex=pending.sections.indexOf(pending.smart.raw)}renderImportModal();return}if(t.id==='dashboardScopePicker'){dashboardScope=t.value;dashboardMaterial='全部';render();return}if(t.id==='dashboardMaterialPicker'){dashboardMaterial=t.value;render();return}if(t.id==='categoryPicker'){categoryFilter=t.value;render();return}if(t.id==='competitorSortPicker'){competitorSort=t.value;render();return}if(t.id==='toggleExcluded'){showExcluded=t.checked;render();return}if(t.id==='planBasisPicker'){const s=p.skus.find(x=>x.id===activeSkuId)||p.skus[0];if(s){s.planBasis=t.value;save();render();}return}if(t.id==='skuPicker'||t.id==='profitSkuPicker'){activeSkuId=t.value;render();return}if(t.dataset.projectField){p[t.dataset.projectField]=t.value;save();if(t.dataset.projectField==='name')$('#crumbProject').textContent=p.name;return}if(t.dataset.skuField){const s=p.skus.find(x=>x.id===activeSkuId)||p.skus[0];if(!s)return;const k=t.dataset.skuField;s[k]=t.type==='number'?n(t.value):t.value;save();if(page==='profit')render();else if(page==='product'&&['purchaseRmb','fx','costUsdOverride'].includes(k))refreshSkuUsdPreview(s);return}}
async function dispatchClick(e){let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action,p=project();if(a==='goto'){navigate(el.dataset.target);return}if(a==='new-project'){let name=prompt('输入项目名称','新的 Amazon 产品调研');if(!name)return;let np=newProject(name.trim());app.projects.push(np);app.activeId=np.id;activeSkuId=null;categoryFilter='全部';save();render();toast('新项目已创建');return}if(a==='open-project'){app.activeId=el.dataset.id;activeSkuId=project().skus[0]?.id||null;categoryFilter='全部';save();navigate('product');return}if(a==='add-sku'){let x=newSku();x.name='新 SKU '+(p.skus.length+1);p.skus.push(x);activeSkuId=x.id;save();render();return}if(a==='remove-sku'&&p.skus.length>1){if(!confirm('确认删除当前 SKU？旧版本不会受到影响。'))return;p.skus=p.skus.filter(s=>s.id!==activeSkuId);activeSkuId=p.skus[0]?.id;save();render();return}if(a==='add-comp'){compModal(null);return}if(a==='edit-comp'){compModal(p.competitors.find(x=>x.id===el.dataset.id));return}if(a==='exclude-comp'){const c=p.competitors.find(x=>x.id===el.dataset.id);if(!c)return;c.excluded=!c.excluded;c.excludeReason=c.excluded?'人工排除':'';markDuplicateRisks(p.competitors);save();render();return}if(a==='close-modal'){closeModal();return}if(a==='confirm-import'){await confirmImport();return}if(a==='download-source'){let b=await getFile(el.dataset.id);if(!b)return toast('无法找到原始文件；可能是浏览器存储已被清理');download(el.dataset.name,b);return}if(a==='export-json'){exportJson();closeModal();return}if(a==='export-csv'){exportCsv();closeModal();return}if(a==='export-print'){closeModal();window.print();return}if(a==='generate-report'){if(p.report&&!confirm('重新生成将覆盖当前编辑框中已保存的结论，是否继续？'))return;p.report=generateRuleReport(p);save();render();toast('已生成规则分析草稿，可继续编辑');return}if(a==='save-report'){p.report=$('#reportEdit').value;save();toast('结论已保存');return}if(a==='save-version'){saveVersion();return}if(a==='select-version'){selectedVersionIds=selectedVersionIds.includes(el.dataset.id)?selectedVersionIds.filter(id=>id!==el.dataset.id):[...selectedVersionIds.slice(-1),el.dataset.id];render();return}if(a==='download-version'){let v=p.versions.find(x=>x.id===el.dataset.id);if(v)exportJson(v.snapshot,`市场调研-${p.name}-V${v.index}.json`);return}if(a==='restore-version'){let v=p.versions.find(x=>x.id===el.dataset.id);if(!v||!confirm(`确认以 V${v.index} 的内容恢复当前工作区？系统将生成新的正式版本，原有历史记录保留。`))return;const oldVersions=p.versions;Object.assign(p,clone(v.snapshot));p.versions=oldVersions;p.versions.push({id:uid(),index:oldVersions.length+1,at:new Date().toISOString(),note:`从 V${v.index} 恢复`,snapshot:snapshot(p)});save();render();toast('已创建恢复版本');return}}
